<span class="line"><span style="color:#C678DD;">public</span><span style="color:#C678DD;"> readonly</span><span style="color:#C678DD;"> ref</span><span style="color:#C678DD;"> struct</span><span style="color:#E5C07B;"> Span</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">T</span><span style="color:#ABB2BF;">&gt;</span></span>
